    }

    /**
     * Validates that the source identifier contains only safe ASCII characters.
     * This prevents injection of control characters or special sequences.
     */
    private boolean isValidSourceIdentifier(String source) {
        if (source == null || source.isEmpty() || source.length() > 64) {
            return false;
        }
        // Check each character is in the allowed ASCII range
        for (int i = 0; i < source.length(); i++) {
            char c = source.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-')) {
                return false;
            }
        }
        return true;
    }

    /**
     * Normalizes the source identifier to canonical form before privilege check.
     * Uses NFKC normalization to collapse compatibility equivalences.
     */
    private String canonicalizeSource(String source) {
        // First normalize to NFKC to handle any compatibility decompositions
        String normalized = Normalizer.normalize(source, Normalizer.Form.NFKC);
        return normalized.toLowerCase(Locale.ROOT);
    }

    /**
     * Determines if the log entry should be treated as privileged.
     * Privileged entries bypass rate limiting and get written to a separate channel.
     */
    private boolean isPrivilegedSource(String source) {
        String canonical = canonicalizeSource(source);
        return PRIVILEGED_SOURCES.contains(canonical);
    }

    /**
     * Rate limits non-privileged sources to prevent log flooding.
     * Returns true if the message should be allowed through.
     */
    private boolean checkRateLimit(String source) {
        int count = rateLimiter.merge(source, 1, Integer::sum);
        return count <= 100;
    }

