        String safeSeverity = severity != null && severity.matches("^(INFO|WARN|ERROR|CRITICAL)$") 
            ? severity : "INFO";

        // Step 5: Write the audit entry
        String prefix = privileged ? "[PRIVILEGED] " : "";
        writeEntry(safeSeverity, source, prefix + safeMessage);

        // Step 6: Privileged sources also trigger immediate flush and alert
        if (privileged) {
            triggerPrivilegedAlert(source, safeMessage);
        }
    }

    private void writeEntry(String severity, String source, String message) throws IOException {
        long timestamp = System.currentTimeMillis();
        String entry = String.format("%d|%s|%s|%s%n", timestamp, severity, source, message);
        Files.writeString(logFile, entry, StandardCharsets.UTF_8, 
            StandardOpenOption.CREATE, StandardOpenOption.APPEND);
    }

    private void triggerPrivilegedAlert(String source, String message) {
        // In production, this would send to a SIEM or alerting system
        // Privileged alerts bypass normal processing pipeline
        System.err.println("PRIVILEGED ALERT from " + source + ": " + message);
    }

    private String sanitizeForLog(String input) {
        if (input == null) return "<null>";
        // Remove control characters and limit length
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Math.min(input.length(), 1024); i++) {
            char c = input.charAt(i);
            if (c >= 0x20 && c < 0x7F) {
                sb.append(c);
            } else {
                sb.append(String.format("\\u%04x", (int) c));
            }
        }
        return sb.toString();
    }

    public void resetRateLimits() {
        rateLimiter.clear();
    }

